CREATE TABLE IF NOT EXISTS presence (session TEXT PRIMARY KEY, last_seen INTEGER NOT NULL, path TEXT); CREATE INDEX IF NOT EXISTS presence_last_seen ON presence (last_seen); CREATE TABLE IF NOT EXISTS daily_visitors (day TEXT NOT NULL, visitor TEXT NOT NULL, PRIMARY KEY (day, visitor)); CREATE TABLE IF NOT EXISTS daily_stats (day TEXT PRIMARY KEY, pageviews INTEGER NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS listing_views (listing_id TEXT NOT NULL, day TEXT NOT NULL, views INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (listing_id, day)); CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, method TEXT NOT NULL, contact TEXT NOT NULL, category TEXT, min_level INTEGER NOT NULL, max_level INTEGER, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS alerts_expires ON alerts (expires_at); CREATE TABLE IF NOT EXISTS alert_hits (alert_id INTEGER NOT NULL, listing_id TEXT NOT NULL, PRIMARY KEY (alert_id, listing_id));
